package dev.thefoolish.generated.anishelf;
import android.content.*;import java.util.*;
public final class ExtensionManager{private final SharedPreferences p;public ExtensionManager(Context c){p=c.getSharedPreferences("extension_state",0);}public ExtensionRecord.State state(String id){try{return ExtensionRecord.State.valueOf(p.getString("state_"+id,ExtensionRecord.State.AVAILABLE.name()));}catch(Exception e){return ExtensionRecord.State.AVAILABLE;}}public void setState(String id,ExtensionRecord.State s){p.edit().putString("state_"+id,s.name()).apply();}public void save(List<ExtensionRecord> items){SharedPreferences.Editor e=p.edit();Set<String> ids=new LinkedHashSet<>();for(ExtensionRecord x:items){ids.add(x.id);e.putString("name_"+x.id,x.name);e.putString("version_"+x.id,x.version);e.putString("repo_"+x.id,x.repoUrl);e.putString("search_"+x.id,x.searchUrl);e.putString("playback_"+x.id,x.playbackUrl);}e.putStringSet("known",ids).apply();}public List<ExtensionRecord> known(){List<ExtensionRecord> out=new ArrayList<>();for(String id:p.getStringSet("known",new LinkedHashSet<>())){ExtensionRecord x=new ExtensionRecord(id,p.getString("name_"+id,id),p.getString("version_"+id,""),p.getString("repo_"+id,""),p.getString("search_"+id,""),p.getString("playback_"+id,""));x.state=state(id);out.add(x);}return out;}public ExtensionRecord find(String id){for(ExtensionRecord x:known())if(x.id.equals(id))return x;return null;}}
